/* EF Core Lab — compare approaches: real EF Core 10 SQL (assets/js/lab-data.js, generated by
 * tools/lab-sql) plus a transparent cost model for round trips, rows, data moved and time. */
(function () {
  "use strict";

  var SQL = window.EF_LAB_SQL || {};

  // ---------------------------------------------------------------------------------------------
  // Cost model. Every constant is shown on the page ("How the estimate works").
  // ---------------------------------------------------------------------------------------------
  var NETWORKS = [
    { id: "local", label: "Same machine", latency: 0.1, mbps: 2000 },
    { id: "dc", label: "Same data centre", latency: 1, mbps: 1000 },
    { id: "cloud", label: "Cloud region", latency: 5, mbps: 200 },
    { id: "far", label: "Cross-region", latency: 40, mbps: 50 },
  ];
  var M = {
    perCommandDb: 0.1,      // ms of database work per statement (parse/plan cache/execute overhead)
    perRowRead: 0.002,      // ms per row the database reads (index or page access)
    perRowWritten: 0.02,    // ms per row the database writes (incl. index maintenance and log)
    perCommandEf: 0.03,     // ms of EF Core work per command (query cache lookup, command setup)
    matTracked: 0.004,      // ms to materialize and track one entity (snapshot, identity map, fix-up)
    matUntracked: 0.0015,   // ms to materialize one entity without tracking
    matProjection: 0.001,   // ms to materialize one projected (DTO / anonymous) row
    perRowProcessed: 0.001, // ms to read one result row that doesn't create a new object
    perEntitySave: 0.01,    // ms of SaveChanges work per entity (DetectChanges, command building)
    maxBatch: 42,           // EF Core's default SQL Server batch size
    minBatch: 4,            // below this, SQL Server statements aren't batched
  };
  var B = { order: 60, customer: 150, address: 100, product: 600, key: 4, name: 20, total: 9, city: 15, orderProj: 45, insertRow: 120, updateRow: 40 };

  var COMPONENTS = [
    { id: "network", label: "Network round trips", phrase: "network round trips", css: "--viz-1" },
    { id: "database", label: "Database work", phrase: "database work", css: "--viz-2" },
    { id: "transfer", label: "Data transfer", phrase: "data transfer", css: "--viz-3" },
    { id: "ef", label: "EF Core processing", phrase: "EF Core processing", css: "--viz-4" },
  ];

  function batches(n) { return n < M.minBatch ? n : Math.ceil(n / M.maxBatch); }
  function txTrips(b) { return b > 1 ? 2 : 0; }   // BEGIN + COMMIT when SaveChanges needs a transaction

  // ---------------------------------------------------------------------------------------------
  // Scenarios. Each approach returns counts; time() turns counts into the cost breakdown.
  // ---------------------------------------------------------------------------------------------
  var SCENARIOS = [
    {
      id: "n-plus-one", title: "N+1 queries", lesson: 12, slug: "12-loading-related-data", playground: "n-plus-one",
      question: "Show a page of orders with each order's customer name.",
      params: [{ id: "n", label: "Orders on the page", min: 10, max: 1000, step: 10, value: 100 }],
      approaches: [
        { id: "loop", label: "Loop + lookup per order (N+1)",
          code: "var orders = await db.Orders.OrderBy(o => o.Id).Take(pageSize).ToListAsync();\nforeach (var o in orders)\n    o.Customer = await db.Customers.FirstAsync(c => c.Id == o.CustomerId);",
          repeat: function (p) { return [1, p.n]; },
          counts: function (p) { return { trips: 1 + p.n, rowsRead: 2 * p.n, rowsReturned: 2 * p.n, bytes: p.n * (B.order + B.customer), ef: 2 * p.n * M.matTracked }; } },
        { id: "include", label: "Include(o => o.Customer)",
          code: "var orders = await db.Orders.OrderBy(o => o.Id).Take(pageSize)\n    .Include(o => o.Customer)\n    .ToListAsync();",
          counts: function (p) { return { trips: 1, rowsRead: 2 * p.n, rowsReturned: p.n, bytes: p.n * (B.order + B.customer), ef: 2 * p.n * M.matTracked }; } },
        { id: "projection", label: "Projection (Select)",
          code: "var rows = await db.Orders.OrderBy(o => o.Id).Take(pageSize)\n    .Select(o => new { o.Id, o.PlacedUtc, o.Total, Customer = o.Customer.Name })\n    .ToListAsync();",
          counts: function (p) { return { trips: 1, rowsRead: 2 * p.n, rowsReturned: p.n, bytes: p.n * B.orderProj, ef: p.n * M.matProjection }; } },
      ],
    },
    {
      id: "cartesian", title: "Cartesian explosion", lesson: 15, slug: "15-split-queries", playground: "split-query",
      question: "Load customers with their orders and their addresses (two collections).",
      params: [
        { id: "c", label: "Customers", min: 10, max: 500, step: 10, value: 100 },
        { id: "o", label: "Orders per customer", min: 1, max: 50, step: 1, value: 30 },
        { id: "a", label: "Addresses per customer", min: 1, max: 10, step: 1, value: 5 },
      ],
      approaches: [
        { id: "single", label: "Include both, single query",
          code: "var customers = await db.Customers.OrderBy(c => c.Id).Take(n)\n    .Include(c => c.Orders)\n    .Include(c => c.Addresses)\n    .ToListAsync();",
          counts: function (p) {
            var rows = p.c * p.o * p.a, entities = p.c + p.c * p.o + p.c * p.a;
            return { trips: 1, rowsRead: entities, rowsReturned: rows, bytes: rows * (B.customer + B.order + B.address), ef: rows * M.perRowProcessed + entities * M.matTracked };
          } },
        { id: "split", label: "Include both + AsSplitQuery()",
          code: "var customers = await db.Customers.OrderBy(c => c.Id).Take(n)\n    .Include(c => c.Orders)\n    .Include(c => c.Addresses)\n    .AsSplitQuery()\n    .ToListAsync();",
          counts: function (p) {
            var rows = p.c + p.c * p.o + p.c * p.a;
            return { trips: 3, rowsRead: 3 * p.c + p.c * p.o + p.c * p.a, rowsReturned: rows, bytes: p.c * B.customer + p.c * p.o * (B.order + B.key) + p.c * p.a * (B.address + B.key), ef: rows * (M.perRowProcessed + M.matTracked) };
          } },
        { id: "projection", label: "Narrow projection + AsSplitQuery()",
          code: "var data = await db.Customers.OrderBy(c => c.Id).Take(n)\n    .Select(c => new { c.Id, c.Name,\n        Totals = c.Orders.Select(o => o.Total).ToList(),\n        Cities = c.Addresses.Select(a => a.City).ToList() })\n    .AsSplitQuery()\n    .ToListAsync();",
          counts: function (p) {
            var rows = p.c + p.c * p.o + p.c * p.a;
            return { trips: 3, rowsRead: 3 * p.c + p.c * p.o + p.c * p.a, rowsReturned: rows, bytes: p.c * (B.key + B.name) + p.c * p.o * (B.total + B.key) + p.c * p.a * (B.city + B.key), ef: rows * M.matProjection };
          } },
      ],
    },
    {
      id: "tracking", title: "Tracking vs no-tracking", lesson: 10, slug: "10-tracking-vs-no-tracking", playground: "tracking",
      question: "Read a customer's orders for a read-only screen or API response.",
      params: [{ id: "n", label: "Rows returned", min: 100, max: 50000, step: 100, value: 5000 }],
      approaches: [
        { id: "tracking", label: "Tracking query (default)",
          code: "var orders = await db.Orders\n    .Where(o => o.CustomerId == customerId)\n    .ToListAsync();",
          counts: function (p) { return { trips: 1, rowsRead: p.n, rowsReturned: p.n, bytes: p.n * B.order, ef: p.n * M.matTracked }; } },
        { id: "no-tracking", label: "AsNoTracking()",
          code: "var orders = await db.Orders.AsNoTracking()\n    .Where(o => o.CustomerId == customerId)\n    .ToListAsync();",
          counts: function (p) { return { trips: 1, rowsRead: p.n, rowsReturned: p.n, bytes: p.n * B.order, ef: p.n * M.matUntracked }; } },
        { id: "projection", label: "Projection (never tracked)",
          code: "var orders = await db.Orders\n    .Where(o => o.CustomerId == customerId)\n    .Select(o => new { o.Id, o.PlacedUtc, o.Total })\n    .ToListAsync();",
          counts: function (p) { return { trips: 1, rowsRead: p.n, rowsReturned: p.n, bytes: p.n * (B.key + 8 + B.total), ef: p.n * M.matProjection }; } },
      ],
    },
    {
      id: "paging", title: "Offset vs keyset paging", lesson: 13, slug: "13-pagination", playground: "pagination",
      question: "Fetch one page of orders deep into a large table.",
      params: [
        { id: "page", label: "Page number", min: 1, max: 10000, step: 1, value: 500 },
        { id: "size", label: "Page size", min: 10, max: 100, step: 10, value: 20 },
      ],
      approaches: [
        { id: "offset", label: "Skip/Take (OFFSET)",
          code: "var page = await db.Orders.OrderBy(o => o.Id)\n    .Skip((pageNumber - 1) * pageSize).Take(pageSize)\n    .Select(o => new { o.Id, o.PlacedUtc, o.Total })\n    .ToListAsync();",
          counts: function (p) { return { trips: 1, rowsRead: p.page * p.size, rowsReturned: p.size, bytes: p.size * (B.key + 8 + B.total), ef: p.size * M.matProjection }; } },
        { id: "keyset", label: "Keyset / seek (WHERE Id > last)",
          code: "var page = await db.Orders.Where(o => o.Id > lastId)\n    .OrderBy(o => o.Id).Take(pageSize)\n    .Select(o => new { o.Id, o.PlacedUtc, o.Total })\n    .ToListAsync();",
          counts: function (p) { return { trips: 1, rowsRead: p.size, rowsReturned: p.size, bytes: p.size * (B.key + 8 + B.total), ef: p.size * M.matProjection }; } },
      ],
    },
    {
      id: "inserts", sqlKey: "saving", title: "Inserting many rows", lesson: 16, slug: "16-efficient-saving", playground: "batching",
      question: "Insert new products.",
      params: [{ id: "n", label: "Rows to insert", min: 1, max: 5000, step: 1, value: 500 }],
      approaches: [
        { id: "loop", label: "SaveChanges per row",
          code: "foreach (var p in newProducts)\n{\n    db.Products.Add(p);\n    await db.SaveChangesAsync();\n}",
          repeat: function (p) { return [p.n]; },
          counts: function (p) { return { trips: p.n, rowsWritten: p.n, rowsReturned: p.n, bytes: p.n * 8, bytesSent: p.n * B.insertRow, ef: p.n * M.perEntitySave }; } },
        { id: "batched", label: "One SaveChanges (batched)",
          code: "db.Products.AddRange(newProducts);\nawait db.SaveChangesAsync();   // up to 42 rows per MERGE batch",
          repeat: function (p) { return [batches(p.n)]; },
          counts: function (p) { var b = batches(p.n); return { trips: b + txTrips(b), rowsWritten: p.n, rowsReturned: p.n, bytes: p.n * 12, bytesSent: p.n * B.insertRow, ef: p.n * M.perEntitySave }; } },
      ],
    },
    {
      id: "updates", sqlKey: "saving", title: "Updating many rows", lesson: 16, slug: "16-efficient-saving", playground: "bulk-update",
      question: "Raise the price of every product in a category by 10%.",
      params: [{ id: "n", label: "Rows to update", min: 1, max: 20000, step: 1, value: 2000 }],
      approaches: [
        { id: "load-modify-save", label: "Load, modify, SaveChanges",
          code: "var products = await db.Products.Where(p => p.CategoryId == categoryId).ToListAsync();\nforeach (var p in products) p.Price *= 1.1m;\nawait db.SaveChangesAsync();",
          repeat: function (p) { return [1, batches(p.n)]; },
          counts: function (p) { var b = batches(p.n); return { trips: 1 + b + txTrips(b), rowsRead: 2 * p.n, rowsWritten: p.n, rowsReturned: p.n, bytes: p.n * B.product, bytesSent: p.n * B.updateRow, ef: p.n * (M.matTracked + M.perEntitySave) }; } },
        { id: "execute-update", label: "ExecuteUpdateAsync (one statement)",
          code: "await db.Products\n    .Where(p => p.CategoryId == categoryId)\n    .ExecuteUpdateAsync(s => s.SetProperty(p => p.Price, p => p.Price * 1.1m));",
          counts: function (p) { return { trips: 1, rowsRead: p.n, rowsWritten: p.n, rowsReturned: 0, bytes: 8, bytesSent: 200, ef: 0 }; } },
      ],
    },
  ];

  // ---------------------------------------------------------------------------------------------
  function time(c, net) {
    var bytes = (c.bytes || 0) + (c.bytesSent || 0);
    return {
      network: c.trips * net.latency,
      database: c.trips * M.perCommandDb + (c.rowsRead || 0) * M.perRowRead + (c.rowsWritten || 0) * M.perRowWritten,
      transfer: bytes / (net.mbps * 1000),
      ef: c.trips * M.perCommandEf + (c.ef || 0),
    };
  }
  function total(t) { return t.network + t.database + t.transfer + t.ef; }

  function fmtMs(ms) {
    if (ms < 1) return ms.toFixed(2) + " ms";
    if (ms < 100) return ms.toFixed(1) + " ms";
    if (ms < 1000) return Math.round(ms) + " ms";
    return (ms / 1000).toFixed(ms < 10000 ? 2 : 1) + " s";
  }
  function fmtNum(n) { return Math.round(n).toLocaleString("en-US"); }
  function fmtBytes(b) {
    if (b < 1024) return Math.round(b) + " B";
    if (b < 1024 * 1024) return (b / 1024).toFixed(b < 10240 ? 1 : 0) + " KB";
    return (b / 1048576).toFixed(1) + " MB";
  }
  function esc(s) { return String(s).replace(/[&<>"]/g, function (ch) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[ch]; }); }

  // ---------------------------------------------------------------------------------------------
  var root = document.querySelector(".lab");
  if (!root) return;
  var tabsEl = document.getElementById("scenario-tabs");
  var panel = document.getElementById("lab-panel");
  var controlsEl = document.getElementById("lab-controls");
  var chartEl = document.getElementById("lab-chart");
  var tableEl = document.getElementById("lab-table");
  var approachesEl = document.getElementById("lab-approaches");
  var tooltip = document.getElementById("lab-tooltip");
  var state = { scenario: SCENARIOS[0], params: {}, network: NETWORKS[2] };

  var requested = new URLSearchParams(location.search).get("scenario");
  state.scenario = SCENARIOS.filter(function (s) { return s.id === requested; })[0] || SCENARIOS[0];

  function buildTabs() {
    tabsEl.innerHTML = SCENARIOS.map(function (s) {
      var on = s === state.scenario;
      return '<button type="button" role="tab" class="lab-tab' + (on ? " active" : "") + '" id="tab-' + s.id + '" aria-controls="lab-panel" aria-selected="' + on +
        '" tabindex="' + (on ? 0 : -1) + '" data-id="' + s.id + '">' + esc(s.title) + '<small>Lesson ' + s.lesson + '</small></button>';
    }).join("");
    panel.setAttribute("aria-labelledby", "tab-" + state.scenario.id);
  }

  tabsEl.addEventListener("click", function (e) {
    var b = e.target.closest("button[data-id]");
    if (b) select(b.getAttribute("data-id"), false);
  });
  tabsEl.addEventListener("keydown", function (e) {
    var i = SCENARIOS.indexOf(state.scenario), n = SCENARIOS.length, next = -1;
    if (e.key === "ArrowRight") next = (i + 1) % n;
    else if (e.key === "ArrowLeft") next = (i - 1 + n) % n;
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = n - 1;
    if (next < 0) return;
    e.preventDefault();
    select(SCENARIOS[next].id, true);
  });

  function select(id, focus) {
    state.scenario = SCENARIOS.filter(function (s) { return s.id === id; })[0];
    state.params = {};
    state.scenario.params.forEach(function (p) { state.params[p.id] = p.value; });
    try { history.replaceState(null, "", "?scenario=" + id); } catch (err) { /* file:// */ }
    buildTabs();
    buildControls();
    buildApproaches();
    update();
    if (focus) document.getElementById("tab-" + id).focus();
  }

  function buildControls() {
    var s = state.scenario;
    document.getElementById("lab-question").innerHTML = "<b>Task:</b> " + esc(s.question) +
      ' <a href="lessons/' + s.slug + '.html">Lesson ' + s.lesson + "</a> · " +
      '<a href="playground/?example=' + s.playground + '">Run it for real in the Playground</a>';
    var html = s.params.map(function (p) {
      return '<label class="lab-control"><span>' + esc(p.label) + ' <output id="out-' + p.id + '">' + fmtNum(state.params[p.id]) + "</output></span>" +
        '<input type="range" data-param="' + p.id + '" min="' + p.min + '" max="' + p.max + '" step="' + p.step + '" value="' + state.params[p.id] + '"></label>';
    }).join("");
    html += '<label class="lab-control"><span>Network</span><select id="lab-network">' + NETWORKS.map(function (n) {
      return '<option value="' + n.id + '"' + (n === state.network ? " selected" : "") + ">" + n.label + " (" + n.latency + " ms, " + n.mbps + " MB/s)</option>";
    }).join("") + "</select></label>";
    controlsEl.innerHTML = html;
  }

  controlsEl.addEventListener("input", function (e) {
    var id = e.target.getAttribute("data-param");
    if (id) {
      state.params[id] = Number(e.target.value);
      document.getElementById("out-" + id).textContent = fmtNum(state.params[id]);
      scheduleUpdate();
    }
  });
  controlsEl.addEventListener("change", function (e) {
    if (e.target.id === "lab-network") {
      state.network = NETWORKS.filter(function (n) { return n.id === e.target.value; })[0];
      scheduleUpdate();
    }
  });

  var pending = false;
  function scheduleUpdate() {
    if (pending) return;
    pending = true;
    requestAnimationFrame(function () { pending = false; update(); });
  }

  function sqlFor(s, a) {
    var all = SQL[s.sqlKey || s.id] || {};
    return all[a.id] || [];
  }

  function buildApproaches() {
    var s = state.scenario;
    approachesEl.innerHTML = '<h2 class="lab-h">The approaches: code and the SQL EF Core 10 generates (SQL Server)</h2>' +
      s.approaches.map(function (a) {
        var cmds = sqlFor(s, a);
        return '<section class="lab-approach" data-approach="' + a.id + '">' +
          "<h3>" + esc(a.label) + '</h3><div class="lab-metrics" data-metrics="' + a.id + '"></div>' +
          '<pre data-label="C#"><code class="language-csharp">' + esc(a.code) + "</code></pre>" +
          cmds.map(function (sql, i) {
            return '<pre data-label="SQL command ' + (i + 1) + '" class="lab-sql"><span class="lab-repeat" data-repeat="' + a.id + ":" + i + '"></span><code class="language-sql">' + esc(sql.trim()) + "</code></pre>";
          }).join("") +
          "</section>";
      }).join("");
    if (window.hljs) approachesEl.querySelectorAll("pre code").forEach(function (c) { try { window.hljs.highlightElement(c); } catch (err) { /* ignore */ } });
    // Long SQL lines scroll horizontally: make each block reachable from the keyboard
    approachesEl.querySelectorAll("pre").forEach(function (pre) { pre.setAttribute("tabindex", "0"); });
  }

  function update() {
    var s = state.scenario, net = state.network;
    var rows = s.approaches.map(function (a) {
      var c = a.counts(state.params), t = time(c, net);
      return { a: a, c: c, t: t, total: total(t) };
    });
    var max = Math.max.apply(null, rows.map(function (r) { return r.total; })) || 1;

    // Legend (identity never by colour alone: the table and tooltips name every component)
    document.getElementById("lab-legend").innerHTML = COMPONENTS.map(function (k) {
      return '<span class="lab-key"><i style="background:var(' + k.css + ')"></i>' + k.label + "</span>";
    }).join("");

    chartEl.innerHTML = rows.map(function (r, i) {
      var segs = COMPONENTS.map(function (k) {
        var w = (r.t[k.id] / max) * 100;
        return w > 0 ? '<span class="lab-seg" style="width:' + w.toFixed(3) + "%;background:var(" + k.css + ')"></span>' : "";
      }).join("");
      return '<div class="lab-row" tabindex="0" data-row="' + i + '" aria-label="' + esc(r.a.label) + ": " + fmtMs(r.total) + '">' +
        '<span class="lab-row-label">' + esc(r.a.label) + "</span>" +
        '<span class="lab-track"><span class="lab-bar">' + segs + '</span><span class="lab-total">' + fmtMs(r.total) + "</span></span></div>";
    }).join("");
    var fastest = rows.slice().sort(function (x, y) { return x.total - y.total; })[0];
    var slowest = rows.slice().sort(function (x, y) { return y.total - x.total; })[0];
    chartEl.setAttribute("aria-label", "Estimated time: " + rows.map(function (r) { return r.a.label + " " + fmtMs(r.total); }).join("; "));
    chartEl.onmousemove = chartEl.onfocusin = function (e) { var row = e.target.closest(".lab-row"); if (row) showTip(rows[+row.getAttribute("data-row")], row, e); };
    chartEl.onmouseleave = chartEl.onfocusout = function () { tooltip.hidden = true; };

    tableEl.innerHTML = "<caption>Numbers behind the chart</caption><thead><tr>" +
      ["Approach", "Round trips", "Rows read", "Rows returned", "Data moved"].concat(COMPONENTS.map(function (k) { return k.label; })).concat(["Total"])
        .map(function (h) { return '<th scope="col">' + h + "</th>"; }).join("") + "</tr></thead><tbody>" +
      rows.map(function (r) {
        return '<tr><th scope="row">' + esc(r.a.label) + "</th><td>" + fmtNum(r.c.trips) + "</td><td>" + fmtNum((r.c.rowsRead || 0) + (r.c.rowsWritten || 0)) +
          "</td><td>" + fmtNum(r.c.rowsReturned || 0) + "</td><td>" + fmtBytes((r.c.bytes || 0) + (r.c.bytesSent || 0)) + "</td>" +
          COMPONENTS.map(function (k) { return "<td>" + fmtMs(r.t[k.id]) + "</td>"; }).join("") + "<td><b>" + fmtMs(r.total) + "</b></td></tr>";
      }).join("") + "</tbody>";

    rows.forEach(function (r) {
      var m = approachesEl.querySelector('[data-metrics="' + r.a.id + '"]');
      if (m) m.innerHTML = '<span><b>' + fmtNum(r.c.trips) + "</b> round trip" + (r.c.trips === 1 ? "" : "s") + "</span><span><b>" + fmtNum(r.c.rowsReturned || 0) +
        "</b> rows returned</span><span><b>" + fmtBytes((r.c.bytes || 0) + (r.c.bytesSent || 0)) + "</b> moved</span><span>≈ <b>" + fmtMs(r.total) + "</b></span>";
      var rep = r.a.repeat ? r.a.repeat(state.params) : null;
      approachesEl.querySelectorAll('[data-repeat^="' + r.a.id + ':"]').forEach(function (span) {
        var i = +span.getAttribute("data-repeat").split(":")[1];
        var times = rep ? rep[i] : 1;
        span.textContent = times > 1 ? "× " + fmtNum(times) + " round trips" : "";
      });
    });

    var dominant = COMPONENTS.slice().sort(function (x, y) { return slowest.t[y.id] - slowest.t[x.id]; })[0];
    var ratio = fastest.total > 0 ? slowest.total / fastest.total : 1;
    document.getElementById("lab-takeaway").innerHTML = ratio < 1.15
      ? "With these settings the approaches cost about the same. Try more rows or a slower network."
      : "<b>" + esc(fastest.a.label) + "</b> is about <b>" + (ratio >= 10 ? Math.round(ratio) : ratio.toFixed(1)) + "×</b> faster than <b>" + esc(slowest.a.label) +
        "</b> here. The slow approach is dominated by <b>" + dominant.phrase + "</b> (" + fmtMs(slowest.t[dominant.id]) + ").";
  }

  function showTip(r, row, e) {
    tooltip.innerHTML = "<b>" + esc(r.a.label) + "</b><table>" + COMPONENTS.map(function (k) {
      var pct = r.total ? Math.round((r.t[k.id] / r.total) * 100) : 0;
      return '<tr><td><i style="background:var(' + k.css + ')"></i>' + k.label + "</td><td>" + fmtMs(r.t[k.id]) + "</td><td>" + pct + "%</td></tr>";
    }).join("") + '<tr class="sum"><td>Total</td><td>' + fmtMs(r.total) + "</td><td></td></tr></table>";
    tooltip.hidden = false;
    var wrap = chartEl.parentElement.getBoundingClientRect(), rr = row.getBoundingClientRect();
    var x = e && e.clientX ? e.clientX - wrap.left + 14 : rr.left - wrap.left + 40;
    x = Math.min(x, wrap.width - tooltip.offsetWidth - 8);
    tooltip.style.left = Math.max(8, x) + "px";
    tooltip.style.top = (rr.bottom - wrap.top + 6) + "px";
  }

  document.getElementById("lab-model").innerHTML =
    "<p>The SQL on this page is <b>real</b>: it's generated by EF Core 10's SQL Server provider (see <code>tools/lab-sql</code>). The times are <b>estimates</b> from a simple, transparent model. They're for comparing approaches and seeing which cost dominates, not for predicting your production numbers. Always measure (Lesson 25).</p>" +
    "<ul>" +
    "<li><b>Network</b> = round trips × latency of the selected network.</li>" +
    "<li><b>Database</b> = " + M.perCommandDb + " ms per statement + " + (M.perRowRead * 1000) + " µs per row read + " + (M.perRowWritten * 1000) + " µs per row written.</li>" +
    "<li><b>Data transfer</b> = bytes moved ÷ the network's bandwidth. Average row sizes: order " + B.order + " B, customer " + B.customer + " B, address " + B.address + " B, product " + B.product + " B (incl. description).</li>" +
    "<li><b>EF Core processing</b> = " + (M.perCommandEf * 1000) + " µs per command + per row: " + (M.matTracked * 1000) + " µs to materialize and track an entity, " + (M.matUntracked * 1000) + " µs without tracking, " + (M.matProjection * 1000) + " µs for a projected row; SaveChanges " + (M.perEntitySave * 1000) + " µs per entity.</li>" +
    "<li><b>Batching</b>: SQL Server batches up to " + M.maxBatch + " statements per round trip, and doesn't batch fewer than " + M.minBatch + ". A SaveChanges that needs several batches adds BEGIN and COMMIT round trips.</li>" +
    "</ul><p>Not modelled: query plan differences, locking and contention, parallelism, caching, connection-pool waits, and server load. The N+1 loop assumes each order has a different customer.</p>";

  select(state.scenario.id, false);
})();
